  "text": ":root:root {\n  --wp-bg: #070a07;\n  --wp-surface: #070a07;\n  --wp-text: #b6f5ae;\n  --wp-text-2: #8ed788;\n  --wp-muted: #5c9a57;\n  --wp-line: #1f3d1d;\n  --wp-line-soft: #142a13;\n  --wp-accent: #39ff14;\n  --wp-on-accent: #031a00;\n  --wp-banner: #0f2a0c;\n  --wp-font:\n    ui-monospace,\n    \"SF Mono\",\n    Menlo,\n    Consolas,\n    monospace;\n  --wp-ui-font:\n    ui-monospace,\n    \"SF Mono\",\n    Menlo,\n    Consolas,\n    monospace;\n  --wp-font-size: 16px;\n  --wp-radius: 0;\n  color-scheme: dark;\n}\n.wp-banner img,\n.wp-avatar img,\n.postBody img,\n.postImage img {\n  filter: grayscale(1) sepia(1) hue-rotate(60deg) saturate(4) brightness(0.75) contrast(1.2);\n}\n.wp-header,\n.wp-tabs,\n.wp-posts .postCard,\n.wp-about,\n.wp-following,\n.wp-contact,\n.wp-page,\n.wp-pages,\n.wp-notfound {\n  border-style: dashed;\n}\n.wp-name a::before {\n  content: \"> \";\n  color: var(--wp-accent);\n}\n.wp-name a::after {\n  content: \"_\";\n  color: var(--wp-accent);\n  animation: wp-blink 1s steps(1) infinite;\n}\n@keyframes wp-blink {\n  50% {\n    opacity: 0;\n  }\n}\n.wp-name {\n  font-weight: 700;\n  letter-spacing: 0;\n}\n.wp-posts .postTitle::before {\n  content: \"## \";\n  color: var(--wp-muted);\n}\n.wp-btn,\n.wp-follow .follow-label,\n.wp-follow-chevron,\n.wp-pager-link,\n.wp-avatar {\n  border-radius: 0;\n}\n::selection {\n  background: var(--wp-accent);\n  color: var(--wp-on-accent);\n}\n"
